// Build server worker: this pattern is why the thread matters.
fn handle(request: Request) -> Response {
    // std::thread's default stack is 2 MiB, not the 8 MiB a main thread gets
    let handle = std::thread::spawn(move || jet::compile(&request.source));
    match handle.join() {
        Ok(Ok(output)) => Response::ok(output.rust),
        Ok(Err(diagnostics)) => Response::diagnostics(diagnostics),
        // never reached: the overflow aborts the whole process first
        Err(_) => Response::internal_error(),
    }
}

